 const [lf,setLf]=useState(LV),[editingLeaderId,setEditingLeaderId]=useState(null),[rf,setRf]=useState(RV),[editingMeetingId,setEditingMeetingId]=useState(null),[excel,setExcel]=useState(null),[winners,setWinners]=useState(null),[photos,setPhotos]=useState([]),[excelRows,setExcelRows]=useState([]);
 const say=(t,k="green")=>{setMsg(t);setKind(k)};
