 async function login(e){e.preventDefault();setSaving(true);const {error}=await supabase.auth.signInWithPassword({email,password});if(error)say(error.message,"red");setSaving(false)}
 async function saveLeader(e){e.preventDefault();if(!ZONAS.includes(lf.zona))return say("Selecciona una de las cinco zonas autorizadas.","red");setSaving(true);const payload={nombre:norm(lf.nombre),zona:lf.zona,telefono:norm(lf.telefono),estado:lf.estado||"Activo"};const query=editingLeaderId?supabase.from("lideres").update(payload).eq("id",editingLeaderId):supabase.from("lideres").insert(payload);const {error}=await query;if(error)say(error.message,"red");else{setLf(LV);setEditingLeaderId(null);setModal("");say(editingLeaderId?"Información del líder actualizada":"Líder guardado");await load()}setSaving(false)}
